SELECT id, 
FROM pcd_im_message
WHERE message_id = #{messageId}

SELECT id, 
FROM pcd_im_message
WHERE conversation_id = #{conversationId}
  AND server_seq > #{serverSeq}
  AND status != 6
ORDER BY server_seq ASC
LIMIT #{limit}

mapper.update:
UPDATE pcd_im_message
SET status = #{status}, update_time = NOW()
WHERE message_id = #{messageId}

UPDATE pcd_im_message
SET status = 5, content = '该消息已被撤回', update_time = NOW()
WHERE message_id = #{messageId}

mapper.select:
SELECT COALESCE(MAX(server_seq), 0)
FROM pcd_im_message
WHERE conversation_id = #{conversationId}

SELECT COUNT(*) FROM pcd_im_message
WHERE conversation_id=#{conversationId} AND receiver_id=#{receiverId}
  AND status IN (0,1)

SELECT id, 
FROM pcd_im_message
WHERE receiver_id = #{receiverId}
  AND status = #{status}
ORDER BY server_seq DESC
LIMIT #{limit}

SELECT id, 
FROM pcd_im_message
WHERE conversation_id = #{conversationId}
  AND status IN

    #{st}


  AND server_seq < #{cursor}


  AND send_time < #{before}

ORDER BY server_seq DESC
LIMIT #{limit}
